package com.bank.spendalign.service;

import java.util.logging.Logger;

// Longest common subsequence via a 2D prefix table.
public class SpendingAlignService {
    private static final Logger log = Logger.getLogger(SpendingAlignService.class.getName());

    public int longestOrderedOverlap(String a, String b) {
        int m = a.length(), n = b.length();
        int[][] dp = new int[m + 1][n + 1];         // dp[i][j] = LCS of prefixes
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                if (a.charAt(i - 1) == b.charAt(j - 1))
                    dp[i][j] = 1 + dp[i - 1][j - 1]; // match extends diagonal
                else
                    dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]); // keep best neighbour
            }
        }
        final int r = dp[m][n];
        log.info(() -> "Longest ordered spending overlap = " + r);
        return r;
    }
}
